-- EatLog: import UK reference foods from CoFID 2021 (McCance and Widdowson's
-- Composition of Foods Integrated Dataset). Values are per 100g, or per 100ml
-- for alcoholic beverages. Sodium in mg; fibre is AOAC fibre.
-- Contains public sector information licensed under the Open Government Licence v3.0.
-- Generated by scripts/cofid/generate_migration.py — edit that, not this file.

create unique index if not exists foods_source_source_id_key
  on public.foods (source, source_id);

on conflict (source, source_id) do update set
  name = excluded.name,
  serving_size = excluded.serving_size,
  serving_unit = excluded.serving_unit,
  calories = excluded.calories,
  protein = excluded.protein,
  carbohydrate = excluded.carbohydrate,
  fat = excluded.fat,
  fibre = excluded.fibre,
  sodium = excluded.sodium,
  sugar = excluded.sugar;
